from src.orders.events import build_order_cancelled_event


def test_renamed_builder_preserves_event_shape() -> None:
    event = build_order_cancelled_event("o-1", "user")
    assert event.name == "order.cancelled"
    assert event.payload == {
        "order_id": "o-1",
        "reason": "user",
    }

